  'support.groupMoney': 'Apoyo económico',
  'support.groupFree': 'Ayudar sin gastar',
  'support.desc': 'Las compras en las tiendas y el apoyo voluntario ayudan a financiar el desarrollo, el mantenimiento y la firma de código. La app completa sigue siendo gratis en GitHub.',
  'support.sponsor': 'GitHub Sponsors',
