  'useCaseCards.marquee.6': 'Notas',
  'useCaseCards.marquee.7': 'Primeros borradores',
  'useCaseCards.marquee.8': 'Respuestas de soporte',
  'useCaseCards.marquee.9': 'Documentación',
  'useCaseCards.marquee.10': 'Actas',
  'engines.label': 'Requisitos',
  'engines.title': 'Según tu idioma y ordenador',
  'engines.desc': 'Necesitas al menos 8 GB de RAM y un sistema de 64 bits: Windows 10 o posterior, macOS 12 o posterior con Apple Silicon, o Linux. No hace falta una tarjeta gráfica dedicada. Para el reconocimiento de voz local puedes elegir entre Whisper y Parakeet.',
  'engines.whisper.name': 'Whisper',
  'engines.whisper.tech': 'vía whisper.cpp',
  'engines.whisper.tagline': 'Más idiomas',
  'engines.whisper.stat.languages.label': 'Idiomas',
  'engines.whisper.stat.languages.value': '99',
  'engines.whisper.stat.hardware.label': 'Hardware',
  'engines.whisper.stat.hardware.value': 'Aceleración por GPU + uso de CPU',
  'engines.whisper.stat.bestfor.label': 'Ideal si',
  'engines.whisper.stat.bestfor.value': 'necesitas más variedad de idiomas',
  'engines.whisper.desc': 'Hay tres tamaños de modelo con distintos requisitos de memoria y potencia de cálculo. Empieza con „Balanced“ a partir de unos 2 GB de memoria gráfica en NVIDIA o Apple Silicon, o unos 4 GB en AMD o Intel. Por debajo de eso, o sin GPU: „Quick & Compact“.',
  'engines.parakeet.name': 'Parakeet',
  'engines.parakeet.tech': 'NVIDIA Parakeet-TDT con soporte para GPU y CPU como alternativa',
  'engines.parakeet.tagline': 'Rápido también en CPU',
  'engines.parakeet.stat.languages.label': 'Idiomas',
  'engines.parakeet.stat.languages.value': '25',
  'engines.parakeet.stat.hardware.label': 'Hardware',
